==== src/app/domain/hero.ts
/**
 * The hero domain model. Every screen in the console reads these types; the
 * closed vocabularies below are the single source for both the roster and the
 * edit form's select options.
 */
export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = ['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5'] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** 0 to 100 */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearance: ClearanceTier;
  readonly missionCount: number;
  /** Percentage, 0 to 100 */
  readonly successRate: number;
  readonly notes: string;
}
==== src/app/domain/hero.service.ts
import { Service, signal } from '@angular/core';
import { EXAMPLE_ROSTER } from './example-roster';
import type { Hero } from './hero';

/** Every field a caller may change. The id is the lookup key, never edited. */
export type HeroChanges = Partial<Omit<Hero, 'id'>>;

/**
 * In-memory roster. There is no backend: the list is seeded from EXAMPLE_ROSTER
 * (example data) and lives only as long as the page. Edits made through `update`
 * are not persisted across a reload.
 */
@Service()
export class HeroService {
