  @apply text-2xl font-semibold tracking-tight;
}

.dashboard__subtitle {
  @apply text-sm text-muted-foreground;
}

.dashboard__recruit {
  @apply shrink-0;
}

.dashboard__stats {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4;
}

.dashboard__section {
